namespace docking.widgets.table.constrainteditor;



/**
 * {@link SpinnerNumberModel} that adds checking to make sure setValue is in the allowed range.  Strangely,
 * the default SpinnerNumberModel has min and max values, but does not check except during the
 * increment/decrement using the spinner widget.
 */
class BoundedSpinnerNumberModel : SpinnerNumberModel {

	public BoundedSpinnerNumberModel(Number value, Comparable<Number> minimum,
			Comparable<Number> maximum, Number stepSize) : base(value, minimum, maximum, stepSize)
    {
	}

	public BoundedSpinnerNumberModel(int value, int minimum, int maximum, int stepSize) : this(Integer.valueOf(value), Integer.valueOf(minimum), Integer.valueOf(maximum), Integer.valueOf(stepSize))
    {
	}

	public BoundedSpinnerNumberModel(double value, double minimum, double maximum,
			double stepSize) : this(Double.valueOf(value), Double.valueOf(minimum), Double.valueOf(maximum), Double.valueOf(stepSize))
    {
	}

	public BoundedSpinnerNumberModel() : base()
    {
	}

	/* @Override */
	public void setValue(object value) {
		if (value != null && value is Number) {
			Comparable minimum = getMinimum();
			Comparable maximum = getMaximum();

			Number val = (Number) value;

			if (minimum != null && minimum.compareTo(val) > 0) {
				return;
			}
			if (maximum != null && maximum.compareTo(val) < 0) {
				return;
			}
			base.setValue(value);
		}

	}

}
